package httpapi

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"slices"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/testdb"
)

const (
	okURL   = "https://shop.example/kampanya"
	unknown = "00000000-0000-4000-8000-00000000dead"

	editSegment = `{"version":1,"match":"all","conditions":[
		{"kind":"enum_attribute","field":"city","op":"eq","value":"istanbul"},
		{"kind":"event","event":"cart_add","within_days":30,"negate":false},
		{"kind":"event","event":"purchase","within_days":30,"negate":true}]}`
	editContent = `{"sms":{"body":"Selam {{first_name}}, indirim burada: {{campaign_url}}"},"email":{"subject":"Sepetin seni bekliyor","body":"Selam {{first_name}}, indirim burada: {{campaign_url}}"}}`
)

// campaignAPI builds the API over a seeded clone. CAMPAIGN_URL_HOSTS comes
// through ConfigFromEnv, as in production, and "now" is the seed anchor so
// audience counts match docs/seed-data.md.
func campaignAPI(t *testing.T) (http.Handler, *pgxpool.Pool) {
	t.Helper()
	url, meta := testdb.Seeded(t)
	env := map[string]string{"ADMIN_TOKEN": token, "CAMPAIGN_URL_HOSTS": "shop.example,kampanya.example"}
	cfg, err := ConfigFromEnv(func(k string) string { return env[k] })
	if err != nil {
		t.Fatal(err)
	}
	p := pool(t, url)
	return handler(t, &Server{Config: cfg, Pool: p, Now: func() time.Time { return meta.AsOf }}), p
}

// fixture is a campaign put straight into a state, with one LLM revision.
type fixture struct{ ID, Revision string }

func insertCampaign(t *testing.T, p *pgxpool.Pool, state string, version int) fixture {
	t.Helper()
	ctx := context.Background()
	var f fixture
	if err := p.QueryRow(ctx, `INSERT INTO campaigns (brief, campaign_url) VALUES ('brief', $1) RETURNING id::text`, okURL).Scan(&f.ID); err != nil {
		t.Fatal(err)
	}
	if err := p.QueryRow(ctx, `INSERT INTO campaign_revisions (campaign_id, n, source, segment, sms_body, email_subject, email_body)
		VALUES ($1, 1, 'llm', $2, 'sms', 'subject', 'body') RETURNING id::text`, f.ID, editSegment).Scan(&f.Revision); err != nil {
		t.Fatal(err)
	}
	// Approval fields are set in every state: the table's CHECKs then accept
	// any state, and the test exercises only the state machine.
	if _, err := p.Exec(ctx, `UPDATE campaigns SET state = $2, version = $3, current_revision_id = $4,
		approved_revision_id = $4, approved_by = 'fixture', approved_at = now() WHERE id = $1`, f.ID, state, version, f.Revision); err != nil {
		t.Fatal(err)
	}
	return f
}

type campaignRow struct {
	State     string
	Version   int
	Revisions int
	Events    []string // "from>to"
	Actors    []string
}

func loadCampaign(t *testing.T, p *pgxpool.Pool, id string) campaignRow {
	t.Helper()
	ctx := context.Background()
	var r campaignRow
	err := p.QueryRow(ctx, `SELECT state::text, version, (SELECT count(*) FROM campaign_revisions WHERE campaign_id = c.id)
		FROM campaigns c WHERE id = $1`, id).Scan(&r.State, &r.Version, &r.Revisions)
	if err != nil {
		t.Fatal(err)
	}
	rows, err := p.Query(ctx, `SELECT coalesce(from_state::text, '') || '>' || to_state::text, actor FROM campaign_events WHERE campaign_id = $1 ORDER BY id`, id)
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	for rows.Next() {
		var e, actor string
		if err := rows.Scan(&e, &actor); err != nil {
			t.Fatal(err)
		}
		r.Events, r.Actors = append(r.Events, e), append(r.Actors, actor)
	}
	if err := rows.Err(); err != nil {
		t.Fatal(err)
	}
	return r
}

// view is the part of a campaign response these tests rely on.
type view struct {
	Campaign struct {
		ID          string `json:"id"`
		Brief       string `json:"brief"`
		State       string `json:"state"`
		Version     *int   `json:"version"`
		CampaignURL string `json:"campaign_url"`
	} `json:"campaign"`
	Revision *struct {
		ID     string `json:"id"`
		N      int    `json:"n"`
		Source string `json:"source"`
	} `json:"revision"`
	Events []struct {
		From  *string `json:"from_state"`
		To    string  `json:"to_state"`
		Actor string  `json:"actor"`
	} `json:"events"`
}

func decodeView(t *testing.T, rec *httptest.ResponseRecorder) view {
	t.Helper()
	var v view
	if err := json.Unmarshal(rec.Body.Bytes(), &v); err != nil {
		t.Fatalf("not a campaign response: %s", rec.Body)
	}
	if v.Campaign.Version == nil {
		t.Fatalf("response has no campaign.version: %s", rec.Body)
	}
	return v
}

func createBody(brief, campaignURL string) string {
	b, _ := json.Marshal(map[string]string{"brief": brief, "campaign_url": campaignURL})
	return string(b)
}
	}
	if f := sseNext(t, frames, 4*time.Second); f.ID != n || f.Data["text"] != "silent" {
		t.Errorf("frame %+v", f)
	}
}

// liveStack runs everything in the test: the API, a River worker with the
// generate worker, and the in-process mock LLM behind the real client.
func liveStack(t *testing.T) (*httptest.Server, *pgxpool.Pool, *mockllm.Server) {
	t.Helper()
	url, meta := testdb.Seeded(t)
	p := pool(t, url)
	set, err := schema.Load()
	if err != nil {
		t.Fatal(err)
	}
	m := mockllm.New(mockllm.Options{})
	mockSrv := httptest.NewServer(m)
	t.Cleanup(mockSrv.Close)
	cl, err := llm.New(llm.Config{BaseURL: mockSrv.URL, APIKey: "test-placeholder", Schemas: set,
		StallTimeout: 2 * time.Second, TotalTimeout: 20 * time.Second})
	if err != nil {
		t.Fatal(err)
	}
	gen := &campaign.Generator{
		Pool: p, Schemas: set, LLM: cl,
		Now:   func() time.Time { return meta.AsOf },
		Rand:  rand.New(rand.NewPCG(1, 2)),
		Sleep: func(ctx context.Context, _ time.Duration) error { return ctx.Err() },
	}
	workers := river.NewWorkers()
	river.AddWorker(workers, campaign.NewGenerateWorker(gen))
	log := slog.New(slog.DiscardHandler)
	rc, err := river.NewClient(riverpgxv5.New(p), jobs.ClientConfig(workers, log))
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	if err := rc.Start(ctx); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		stopCtx, stop := context.WithTimeout(context.Background(), 10*time.Second)
		defer stop()
		_ = rc.Stop(stopCtx)
		cancel()
	})
	s := &Server{
		Config: Config{AdminToken: token, CampaignURLHosts: []string{"shop.example"}},
		Pool:   p, River: rc, Schemas: set,
		Now: func() time.Time { return meta.AsOf },
		Hub: NewHub(ctx, p, log), Heartbeat: time.Second,
	}
	srv := httptest.NewServer(handler(t, s))
	t.Cleanup(srv.Close)
	return srv, p, m
}

func apiCall(t *testing.T, srv *httptest.Server, method, path, body string) (int, map[string]any) {
	t.Helper()
	req, err := http.NewRequest(method, srv.URL+path, strings.NewReader(body))
	if err != nil {
		t.Fatal(err)
	}
	req.Header.Set("Authorization", bearer["Authorization"])
	resp, err := srv.Client().Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	var out map[string]any
	_ = json.NewDecoder(resp.Body).Decode(&out)
	return resp.StatusCode, out
}

func startGenerate(t *testing.T, srv *httptest.Server, id string, version int) string {
	t.Helper()
	code, body := apiCall(t, srv, "POST", "/api/campaigns/"+id+"/generate", versionBody(version))
	u, _ := body["events_url"].(string)
	if code != http.StatusAccepted || !isEventsURL(u, id) {
		t.Fatalf("generate: %d %v", code, body)
	}
	return u
}

// collect reads one generation's stream to its end.
func sseCollect(t *testing.T, srv *httptest.Server, path string, header map[string]string) []sseFrame {
	t.Helper()
	_, frames := openStream(t, srv, path, header)
	var out []sseFrame
	timeout := time.After(60 * time.Second)
	for {
		select {
		case f, ok := <-frames:
			if !ok {
				return out
			}
			if !f.Comment {
				out = append(out, f)
			}
		case <-timeout:
			t.Fatalf("the stream did not end; got %d events", len(out))
		}
	}
}

// TestGenerateEndToEnd: create, generate and watch the stream with a real
// worker. Events arrive in order, the deltas rebuild the stored copy, a
// reconnect gets only later events, and a regenerate streams only its own
// events.
func TestGenerateEndToEnd(t *testing.T) {
	srv, _, _ := liveStack(t)
	code, created := apiCall(t, srv, "POST", "/api/campaigns", createBody(specBrief, okURL))
	if code != http.StatusCreated {
		t.Fatalf("create: %d %v", code, created)
	}
	id := created["campaign"].(map[string]any)["id"].(string)
	events := sseCollect(t, srv, startGenerate(t, srv, id, 0), bearer)

	var types []string
	for i, f := range events {
		if i > 0 && f.ID <= events[i-1].ID {
			t.Errorf("ids out of order: %d after %d", f.ID, events[i-1].ID)
		}
		if len(types) == 0 || f.Event != "delta" || types[len(types)-1] != "delta" {
			types = append(types, f.Event)
		}
	}
	if want := []string{"started", "segment_ready", "delta", "done"}; strings.Join(types, ",") != strings.Join(want, ",") {
		t.Fatalf("event types %v, want %v", types, want)
	}

	code, view := apiCall(t, srv, "GET", "/api/campaigns/"+id, "")
	if code != http.StatusOK || view["campaign"].(map[string]any)["state"] != "in_review" {
		t.Fatalf("campaign after done: %d %v", code, view["campaign"])
	}
	rev := view["revision"].(map[string]any)
	rebuilt := map[string]string{}
	for _, f := range events {
		if f.Event == "delta" {
			field, _ := f.Data["field"].(string)
			text, _ := f.Data["text"].(string)
			rebuilt[field] += text
		}
	}
	if rebuilt["sms.body"] != rev["sms_body"] || rebuilt["email.subject"] != rev["email_subject"] || rebuilt["email.body"] != rev["email_body"] {
		t.Errorf("deltas rebuild %q; stored revision %v", rebuilt, rev)
	}

	// Reconnect after segment_ready: only the later events come back.
	path := "/api/campaigns/" + id + "/events"
	resumed := sseCollect(t, srv, path, map[string]string{"Authorization": bearer["Authorization"], "Last-Event-ID": strconv.FormatInt(events[1].ID, 10)})
	if len(resumed) != len(events)-2 || resumed[0].ID != events[2].ID || resumed[len(resumed)-1].Event != "done" {
		t.Errorf("resumed %d events from id %d, want the %d after segment_ready", len(resumed), resumed[0].ID, len(events)-2)
	}

	// Regenerate: the new stream starts with its own started event and does
	// not end on the first generation's done.
	version := int(view["campaign"].(map[string]any)["version"].(float64))
	again := sseCollect(t, srv, startGenerate(t, srv, id, version), bearer)
	if len(again) < 3 || again[0].Event != "started" || again[0].ID <= events[len(events)-1].ID || again[len(again)-1].Event != "done" {
		t.Errorf("regenerate stream %+v", again)
	}
}

