	p, _ := seededPool(t)
	ctx := context.Background()
	a, b := newCampaignID(t, p), newCampaignID(t, p)
	payloads := []map[string]any{{"n": 1.0}, {"field": "sms.body", "text": "Mer"}, {"revision_id": "r"}}
