	return ScoreInput{
		Case:     abandonersCase(),
		Outcome:  OutcomeValid,
		Rule:     segment.Rule{Match: "all", Conditions: []segment.Condition{noPurchase30, cityIstanbul, cartAdd30}},
		Copy:     goodCopy(),
		Audience: rightAudience(),
		Fixtures: handFixtures(),
		Total:    320,
	}
