// Plan 3, 1.2 and 1.7: the pure reducer over generation events.
//
// Contract assumed (src/stream/reducer.ts):
//   initialState(): GenState
//   reduce(state: GenState, e: GenEvent): GenState    pure, never mutates state
//   GenEvent { id: number; event: string; data: any }
//   GenState { phase: 'idle' | 'streaming' | 'done' | 'failed'; version: number | null;
//              segment: unknown | null; fields: Record<string, string>; attempt: number;
//              errors: unknown[]; lastEventId: number }
import { describe, expect, it } from 'vitest'
import { initialState, reduce, type GenEvent, type GenState } from './reducer'

function run(events: GenEvent[], from: GenState = initialState()): GenState {
  return events.reduce(reduce, from)
}

function deepFreeze<T>(o: T): T {
  if (o && typeof o === 'object') {
    Object.values(o).forEach(deepFreeze)
    Object.freeze(o)
  }
  return o
}

const segmentReady = (id: number): GenEvent => ({
  id,
  event: 'segment_ready',
  data: { rule: { version: 1, match: 'all', conditions: [] }, description: 'Istanbul', counts: { total: 3 } },
})
const delta = (id: number, field: string, text: string, attempt = 1): GenEvent => ({
  id,
  event: 'delta',
  data: { stage: 'content', attempt, field, text },
})

describe('reducer', () => {
  it('starts idle', () => {
    const s = initialState()
    expect(s.phase).toBe('idle')
    expect(s.lastEventId).toBe(0)
    expect(s.fields).toEqual({})
  })

  it('applies events in order', () => {
    const s = run([
      { id: 10, event: 'started', data: { version: 3 } },
      segmentReady(11),
      delta(12, 'sms.body', 'Mer'),
      delta(13, 'sms.body', 'haba'),
      delta(14, 'email.subject', 'Sepet'),
      { id: 15, event: 'done', data: { revision_id: 'r1' } },
    ])
    expect(s.phase).toBe('done')
    expect(s.version).toBe(3)
    expect(s.segment).not.toBeNull()
    expect(s.fields).toEqual({ 'sms.body': 'Merhaba', 'email.subject': 'Sepet' })
    expect(s.lastEventId).toBe(15)
  })

  it('ignores replayed ids at or below lastEventId', () => {
    const events = [{ id: 10, event: 'started', data: { version: 1 } }, delta(11, 'sms.body', 'Mer'), delta(12, 'sms.body', 'haba')]
    const once = run(events)
    const replayed = run([...events, delta(11, 'sms.body', 'Mer'), delta(12, 'sms.body', 'haba')], initialState())
    expect(replayed.fields['sms.body']).toBe('Merhaba')
    expect(run([delta(12, 'sms.body', 'haba')], once).fields['sms.body']).toBe('Merhaba')
    expect(run([delta(5, 'sms.body', 'x')], once).lastEventId).toBe(12)
  })

  it('resets everything on started', () => {
    const first = run([
      { id: 1, event: 'started', data: { version: 1 } },
      segmentReady(2),
      delta(3, 'sms.body', 'old'),
      { id: 4, event: 'attempt_failed', data: { stage: 'content', attempt: 1, errors: [{ path: '/sms/body', code: 'x', message: 'm' }] } },
    ])
    const s = reduce(first, { id: 9, event: 'started', data: { version: 2 } })
    expect(s.version).toBe(2)
    expect(s.phase).toBe('streaming')
    expect(s.segment).toBeNull()
    expect(s.fields).toEqual({})
    expect(s.errors).toEqual([])
    expect(s.lastEventId).toBe(9)
  })

  it('clears the copy and records errors on attempt_failed', () => {
    const errors = [{ path: '/sms/body', code: 'unknown_variable', message: 'no {{password}}' }]
    const s = run([
      { id: 1, event: 'started', data: { version: 1 } },
      segmentReady(2),
      delta(3, 'sms.body', 'Merhaba {{password}}'),
      { id: 4, event: 'attempt_failed', data: { stage: 'content', attempt: 1, errors } },
    ])
    expect(s.fields).toEqual({})
    expect(s.errors).toEqual(errors)
    expect(s.phase).toBe('streaming')
    expect(s.segment).not.toBeNull() // a content retry keeps the segment
    const next = run([delta(5, 'sms.body', 'Merhaba', 2)], s)
    expect(next.fields['sms.body']).toBe('Merhaba')
    expect(next.attempt).toBe(2)
  })

  it('treats done and failed as terminal', () => {
    const done = run([{ id: 1, event: 'started', data: { version: 1 } }, delta(2, 'sms.body', 'a'), { id: 3, event: 'done', data: {} }])
    expect(run([delta(4, 'sms.body', 'b')], done).fields['sms.body']).toBe('a')
    expect(run([{ id: 4, event: 'failed', data: { reason: 'x' } }], done).phase).toBe('done')

    const failed = run([{ id: 1, event: 'started', data: { version: 1 } }, { id: 2, event: 'failed', data: { reason: 'refusal', stage: 'segment' } }])
    expect(failed.phase).toBe('failed')
    expect(run([delta(3, 'sms.body', 'late')], failed).fields).toEqual({})
  })

  it('ignores unknown event types but still advances the cursor', () => {
    const s = run([{ id: 1, event: 'started', data: { version: 1 } }, { id: 2, event: 'something_new', data: {} }])
    expect(s.phase).toBe('streaming')
    expect(s.lastEventId).toBe(2)
  })

  it('is pure', () => {
    const s = deepFreeze(run([{ id: 1, event: 'started', data: { version: 1 } }, delta(2, 'sms.body', 'a')]))
    const next = reduce(s, delta(3, 'sms.body', 'b'))
    expect(next).not.toBe(s)
    expect(s.fields['sms.body']).toBe('a')
    expect(next.fields['sms.body']).toBe('ab')
  })
})

// Plan 3, 1.7: the fetch-based SSE reader. The parser is fed raw text
// chunks as they come off the stream.
//
// Contract assumed (src/api/sse.ts):
//   SSEMessage { id: string | null; event: string; data: string }
//   createSSEParser(onMessage: (m: SSEMessage) => void): { push(chunk: string): void; end(): void }
//   openEventStream(url, { token, lastEventId?, signal?, fetch?, onMessage }): Promise<'ended' | 'aborted'>
import { describe, expect, it, vi } from 'vitest'
import { createSSEParser, openEventStream, type SSEMessage } from './sse'

function parseAll(chunks: string[]): SSEMessage[] {
  const out: SSEMessage[] = []
  const p = createSSEParser((m) => out.push(m))
  chunks.forEach((c) => p.push(c))
  p.end()
  return out
}

const frame = 'id: 7\nevent: delta\ndata: {"field":"sms.body","text":"Mer"}\n\n'

describe('SSE parser', () => {
  it('parses one frame', () => {
    expect(parseAll([frame])).toEqual([{ id: '7', event: 'delta', data: '{"field":"sms.body","text":"Mer"}' }])
  })

  it('handles chunks split anywhere, including inside a field name and the blank line', () => {
    const whole = frame + 'id: 8\nevent: done\ndata: {}\n\n'
    const want = parseAll([whole])
    for (let i = 1; i < whole.length; i++) {
      expect(parseAll([whole.slice(0, i), whole.slice(i)])).toEqual(want)
    }
    expect(parseAll(whole.split(''))).toEqual(want)
  })

  it('skips heartbeat comments', () => {
    const out = parseAll([': heartbeat\n\n', frame, ':\n\n', ': ping\n'])
    expect(out).toHaveLength(1)
    expect(out[0].event).toBe('delta')
  })

  it('joins multi-line data with newlines', () => {
    expect(parseAll(['event: x\ndata: a\ndata: b\ndata:\ndata: c\n\n'])[0].data).toBe('a\nb\n\nc')
  })

  it('accepts CRLF and CR line endings', () => {
    expect(parseAll(['id: 1\r\nevent: x\r\ndata: y\r\n\r\n'])).toEqual([{ id: '1', event: 'x', data: 'y' }])
    expect(parseAll(['id: 1\revent: x\rdata: y\r\r'])).toEqual([{ id: '1', event: 'x', data: 'y' }])
  })

  it('strips one leading space only, and defaults the event to message', () => {
    expect(parseAll(['data:  two spaces\n\n'])[0]).toEqual({ id: null, event: 'message', data: ' two spaces' })
  })

  it('drops an event cut off before its blank line', () => {
    expect(parseAll([frame, 'id: 9\nevent: delta\ndata: {"partial"'])).toHaveLength(1)
  })

  it('ignores a frame with no data', () => {
    expect(parseAll(['event: x\n\n'])).toEqual([])
  })
})

function streamResponse(chunks: string[], status = 200): Response {
  const enc = new TextEncoder()
  const body = new ReadableStream<Uint8Array>({
    start(c) {
      chunks.forEach((s) => c.enqueue(enc.encode(s)))
      c.close()
    },
  })
  return new Response(body, { status, headers: { 'Content-Type': 'text/event-stream' } })
}

describe('openEventStream', () => {
  it('sends the token only in the Authorization header, and Last-Event-ID when resuming', async () => {
    const fetchMock = vi.fn(async (_url: string, _init?: RequestInit) => streamResponse([frame]))
    const got: SSEMessage[] = []
    const result = await openEventStream('/api/campaigns/c/events?after=4', {
      token: 'tok',
      lastEventId: 6,
      fetch: fetchMock as unknown as typeof fetch,
      onMessage: (m) => got.push(m),
    })
    expect(result).toBe('ended')
    expect(got).toHaveLength(1)
    const [url, init] = fetchMock.mock.calls[0]
    expect(url).toBe('/api/campaigns/c/events?after=4')
    expect(url).not.toContain('tok')
    const h = new Headers(init?.headers)
    expect(h.get('Authorization')).toBe('Bearer tok')
    expect(h.get('Last-Event-ID')).toBe('6')
    expect(h.get('Accept')).toBe('text/event-stream')
  })

  it('reports aborted when the signal fires', async () => {
    const ctl = new AbortController()
    const fetchMock = vi.fn(async (_u: string, init?: RequestInit) => {
      return new Promise<Response>((_, reject) => init?.signal?.addEventListener('abort', () => reject(new DOMException('aborted', 'AbortError'))))
    })
    const p = openEventStream('/x', { token: 't', signal: ctl.signal, fetch: fetchMock as unknown as typeof fetch, onMessage: () => {} })
    ctl.abort()
    await expect(p).resolves.toBe('aborted')
  })

  it('rejects with the status on a non-2xx answer', async () => {
    const fetchMock = vi.fn(async () => new Response('{"errors":[]}', { status: 401 }))
    await expect(openEventStream('/x', { token: 't', fetch: fetchMock as unknown as typeof fetch, onMessage: () => {} })).rejects.toMatchObject({
      status: 401,
    })
  })
})

// Plan 3, 1.3: 422 issue paths carry the /revision prefix. Each known path
// goes to its field; anything else goes to the form-level list, so no
// error is ever dropped.
//
// Contract assumed (src/api/issues.ts):
//   Issue { path: string; code: string; message: string }
//   mapIssues(issues: Issue[]): { sms: Issue[]; emailSubject: Issue[]; emailBody: Issue[];
//                                 segment: Issue[]; form: Issue[] }
import { describe, expect, it } from 'vitest'
import { mapIssues, type Issue } from './issues'

const issue = (path: string, code = 'c'): Issue => ({ path, code, message: `${code} at ${path}` })

describe('mapIssues', () => {
  it('maps the three copy fields exactly', () => {
    const m = mapIssues([
      issue('/revision/content/sms/body', 'contains_url'),
      issue('/revision/content/email/subject', 'too_long'),
      issue('/revision/content/email/body', 'unknown_variable'),
    ])
    expect(m.sms.map((i) => i.code)).toEqual(['contains_url'])
    expect(m.emailSubject.map((i) => i.code)).toEqual(['too_long'])
    expect(m.emailBody.map((i) => i.code)).toEqual(['unknown_variable'])
    expect(m.segment).toEqual([])
    expect(m.form).toEqual([])
  })

  it('sends anything under /revision/segment to the segment card', () => {
    const m = mapIssues([issue('/revision/segment'), issue('/revision/segment/conditions/0/value'), issue('/revision/segment/match')])
    expect(m.segment).toHaveLength(3)
  })

  it('sends version, base_revision_id and unmapped paths to the form list', () => {
    const paths = [
      '/version',
      '/base_revision_id',
      '',
      '/revision',
      '/revision/content',
      '/revision/content/sms',
      '/revision/content/email/bodyx',
      '/revision/segmentx',
      '/revision/content/sms/body/0',
      '/something/else',
    ]
    const m = mapIssues(paths.map((p) => issue(p)))
    expect(m.form.map((i) => i.path)).toEqual(paths)
    expect(m.sms).toEqual([])
    expect(m.segment).toEqual([])
  })

  it('never drops an issue and keeps the order within a list', () => {
    const all = [
      issue('/revision/content/sms/body', 'a'),
      issue('/x', 'b'),
      issue('/revision/content/sms/body', 'c'),
      issue('/revision/segment/conditions/1', 'd'),
      issue('/revision/content/email/body', 'e'),
    ]
    const m = mapIssues(all)
    const total = m.sms.length + m.emailSubject.length + m.emailBody.length + m.segment.length + m.form.length
    expect(total).toBe(all.length)
    expect(m.sms.map((i) => i.code)).toEqual(['a', 'c'])
  })
})

